# ds::external-source: checked 2026-11-17 https://github.com/coder/ghostty-web
#   (README, demo/index.html) taken from it: `init()` then `new Terminal({...})`, `open(el)`,
#   `onData`, `write`, `onResize`, FitAddon (`fit()`, `observeResize()`); raw text both ways,
#   a JSON {"type":"resize"} message; the npm build embeds its WASM as base64, so this one
#   file is all the page loads
GHOSTTY_WEB = "https://cdn.jsdelivr.net/npm/ghostty-web@0.4.0/dist/ghostty-web.js"
LOCAL_HOSTS = {"localhost", "127.0.0.1", "::1"}
# Who may frame the Terminal's page: pages on this machine only (the app). A site that framed
# it could otherwise show your shell inside its own page and send it messages.
FRAME_ANCESTORS = " ".join(
    [
        "frame-ancestors",
        "'self'",
        *(f"{scheme}://{host}:*" for scheme in ("http", "https") for host in ("localhost", "127.0.0.1", "[::1]")),
    ]
)
READ_SIZE = 65536


def shell_command() -> str:
    """The shell the Terminal runs: $SHELL, else /bin/bash."""
    return os.environ.get("SHELL", "/bin/bash")


# The page the Terminal pane frames. Everforest, as the app (assets/app.css).
PAGE = """<!doctype html>
<html>
<head>
<meta charset="utf-8">
<title>Terminal</title>
<style>
  html, body { margin: 0; height: 100%; background: THEME_BACKGROUND; overflow: hidden; }
  /* ghostty-web makes #term contenteditable: focused by a key (Alt+Right), not a click, the
     browser drew its own black text caret at the top left. The cursor is ghostty's block */
  #term { position: absolute; inset: 4px 0 0 6px; caret-color: transparent; outline: none; }
  #note { position: absolute; bottom: 6px; right: 10px; font: 12px sans-serif; color: #e67e80; }
</style>
</head>
<body>
<div id="term"></div>
<div id="note"></div>
<script type="module">
  import { init, Terminal, FitAddon } from "GHOSTTY_WEB";
  const note = document.getElementById("note");
  await init();
  // Sharp text at the size your own terminal uses (FONT_PT points, at SCREEN_SCALE). The app's
  // browser zoom (eg 110%) would make each character cell a fraction of a screen pixel (ghostty
  // rounds cells to whole CSS pixels), smearing the text. So the box undoes the zoom with CSS
  // zoom, and ghostty draws at the monitor's own pixel ratio: every cell is whole screen pixels.
  const browserZoom = window.devicePixelRatio / SCREEN_SCALE;
  document.getElementById("term").style.zoom = String(1 / browserZoom);
  // ghostty-web 0.4.0's Terminal doesn't pass a devicePixelRatio option on to its renderer,
  // which reads the window's: this page (only) reports the monitor's own ratio
  Object.defineProperty(window, "devicePixelRatio", { get: () => SCREEN_SCALE });
  const term = new Terminal({
    fontSize: Math.round(FONT_PT * 96 / 72),
    fontFamily: '"JetBrainsMono Nerd Font", "JetBrains Mono", monospace',
    cursorBlink: true,
    scrollback: 10000,
    // your Omarchy theme's terminal colours, all 16 (terminal_theme(), read per page load)
    theme: THEME_JSON,
  });
  const fit = new FitAddon();
  term.loadAddon(fit);
  term.open(document.getElementById("term"));
  fit.fit();
  fit.observeResize();
  // One shell per connection. It ends when you exit it, or when the backend restarts (it does
  // on every code change while developing): the note says so, and Enter starts a new one.
  const ENDED = "shell ended: press Enter for a new one";
  let ws = null;
  function connect() {
    note.textContent = "";
    const scheme = location.protocol === "https:" ? "wss" : "ws";
    const socket = new WebSocket(`${scheme}://${location.host}/terminal/ws?cols=${term.cols}&rows=${term.rows}`);
    socket.onmessage = (event) => term.write(event.data);
    socket.onclose = () => { if (ws === socket) note.textContent = ENDED; };
    ws = socket;
  }
  connect();
  term.onData((data) => {
    if (ws.readyState === 1) return ws.send(data);
    // the shell is gone: Enter starts a new one, under what the old one left on screen
    if (ws.readyState === 3 && data === "\\r") { term.write("\\r\\n"); connect(); }
  });
  term.onResize(({ cols, rows }) => ws.readyState === 1 && ws.send(JSON.stringify({ type: "resize", cols, rows })));
  term.focus();
  // Alt+I: the inline chat (inline_terminal.py, POST /inline_terminal). Its box is in the
  // app's page, in this pane's title strip (assets/frame_ask.js), so it never covers the
  // shell; this page does the shell's part: the screen's text and the ask go to the AI, and its
  // command is pasted at the prompt, never run (you press Enter). Not part of the chat: the call
  // shows in the debug log, as a cell's inline chat.
  const TOKEN = new URLSearchParams(location.search).get("token") || "";
  const fullScreenProgram = () => term.buffer.active.type === "alternate";
  function screenText() {
    const buffer = term.buffer.active, lines = [];
    for (let y = Math.max(0, buffer.length - term.rows); y < buffer.length; y++) {
      lines.push(buffer.getLine(y)?.translateToString(true) ?? "");
    }
    return lines.join("\\n").replace(/\\n+$/, "");
  }
  // for the e2e tests (tests/services/ui/e2e): what the shell shows and how its cursor is
  // drawn, read from this page itself (another site can't reach into it)
  window.smashTerminal = {
    text: screenText,
    cursor: () => ({ blink: term.options.cursorBlink, style: term.options.cursorStyle }),
    theme: () => term.options.theme,
  };
  const FULL_SCREEN = "a full-screen program is running: go back to a prompt first";
  async function ask(id, instruction) {
    // a paste would go into the program (vim, less), not to a prompt
    if (fullScreenProgram()) return { id, error: FULL_SCREEN };
    try {
      const response = await fetch("/inline_terminal", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ token: TOKEN, instruction, screen: screenText() }),
      });
      return { id, ...(await response.json()) };
    } catch (error) {
      return { id, error: `the request failed: ${error}` };
    }
  }
  // the app's messages (assets/panes.js, assets/frame_ask.js). Only from the app: the page
  // framing this one, on this machine. Any site may try to frame this page; without the
  // origin check its messages could type into the shell (the response's frame-ancestors
  // refuses the framing too, page())
  const LOCAL = new Set(LOCAL_HOSTS_JSON);
  const fromApp = (event) => {
    if (event.source !== parent || !event.data) return false;
    try { return LOCAL.has(new URL(event.origin).hostname.replace(/^\\[|\\]$/g, "")); } catch { return false; }
  };
  window.addEventListener("message", async (event) => {
    if (!fromApp(event)) return;
    const data = event.data;
    // the app moved the cursor here (Alt+Left / Alt+Right, Alt+`, the ask box closed)
    if (data.type === "delulu-focus") {
      cursorActive(true);
      term.focus();
    }
    if (data.type === "delulu-ask-send") {
      parent.postMessage({ type: "delulu-ask-answer", ...(await ask(data.id, data.ask)) }, event.origin);
    }
    if (data.type === "delulu-ask-paste") {
      // a full-screen program started meanwhile: say so, with the command, and type nothing
      if (fullScreenProgram()) {
        const error = `a full-screen program is running; the command was: ${data.command}`;
        return parent.postMessage({ type: "delulu-ask-answer", id: data.id, error }, event.origin);
      }
      term.paste(data.command);
      parent.postMessage({ type: "delulu-ask-answer", id: data.id, pasted: true }, event.origin);
    }
  });
  // the app focuses this frame on Alt+`
  window.addEventListener("focus", () => term.focus());
  // the cursor: a blinking block while this pane has the keys; when you are in another pane, a
  // steady underline (ghostty-web 0.4 draws no hollow block), so it stops catching the eye
  const cursorActive = (on) => {
    term.options.cursorBlink = on;
    term.options.cursorStyle = on ? "block" : "underline";
  };
  window.addEventListener("focus", () => cursorActive(true));
  window.addEventListener("blur", () => cursorActive(false));
  cursorActive(document.hasFocus());
  // The pane's own keys (Alt+` or Alt+Enter hide, with Shift full screen) work from inside it
  // too: the shell would get them otherwise. Sent to the app, which runs them (assets/panes.js).
  document.addEventListener("keydown", (event) => {
    if (!event.altKey || event.ctrlKey || event.metaKey) return;
    if (event.code === "KeyI" && !event.shiftKey) {
      event.preventDefault();
      event.stopImmediatePropagation();
      // Shortcut.INLINE_EDIT: the inline chat's key everywhere in the app; its box is the
      // app's (assets/frame_ask.js), so the app opens it (again: closes it)
      parent.postMessage({ type: "delulu-ask-toggle" }, "*");
      return;
    }
    if (event.code === "KeyW" && !event.shiftKey) {
      // Shortcut.CLOSE_ALL: every panel closes, this one too
      event.preventDefault();
      event.stopImmediatePropagation();
      parent.postMessage({ type: "delulu-press", keys: "Alt+W" }, "*");
      return;
    }
    if ((event.key === "ArrowLeft" || event.key === "ArrowRight") && !event.shiftKey) {
      // Shortcut.NEXT_PANE / PREV_PANE: out of the shell, to the pane beside it
      event.preventDefault();
      event.stopImmediatePropagation();
      parent.postMessage({ type: "delulu-press", keys: `Alt+${event.key}` }, "*");
      return;
    }
    if (event.code !== "Backquote" && event.key !== "Enter") return;
    event.preventDefault();
    event.stopImmediatePropagation();
    parent.postMessage({ type: "delulu-press", keys: event.shiftKey ? "Alt+Shift+`" : "Alt+`" }, "*");
  }, true);
</script>
</body>
</html>
""".replace("GHOSTTY_WEB", GHOSTTY_WEB).replace("LOCAL_HOSTS_JSON", json.dumps(sorted(LOCAL_HOSTS)))

# where the font size of the terminal you use outside the app is read, first found wins:
# (config file under ~/.config, the line's key)
TERMINAL_CONFIGS = (("ghostty/config", "font-size"), ("kitty/kitty.conf", "font_size"))
DEFAULT_FONT_PT = 9.0  # Omarchy's own terminals' size


def terminal_font_pt() -> float:
    """Your own terminal's font size, in points (ghostty's, else kitty's, else Omarchy's 9)."""
    for name, key in TERMINAL_CONFIGS:
        path = Path.home() / ".config" / name
        if not path.is_file():
            continue
        for line in path.read_text(errors="replace").splitlines():
            found, _, value = line.replace("=", " ").strip().partition(" ")
            if found == key:
                with contextlib.suppress(ValueError):
                    return float(value.strip())
    return DEFAULT_FONT_PT


# Your terminal's colours: the ghostty theme of the Omarchy theme you are on (it changes with
# `omarchy theme`), else the repo's copy of Everforest, the app's own (a machine without
# Omarchy)
OMARCHY_GHOSTTY_THEME = Path.home() / ".local/state/omarchy/current/theme/ghostty.conf"
EVERFOREST_THEME = Path(__file__).parents[1] / "ghostty-everforest.conf"
# ghostty's palette = N=#rrggbb, as ghostty-web's theme keys (0 to 15)
ANSI = [
    *("black", "red", "green", "yellow", "blue", "magenta", "cyan", "white"),
    *("brightBlack", "brightRed", "brightGreen", "brightYellow"),
    *("brightBlue", "brightMagenta", "brightCyan", "brightWhite"),
]
# ghostty's own keys for the rest
GHOSTTY_KEYS = {
    "background": "background",
    "foreground": "foreground",
    "cursor-color": "cursor",
    "cursor-text": "cursorAccent",
    "selection-background": "selectionBackground",
    "selection-foreground": "selectionForeground",
}


def read_ghostty_theme(path: Path) -> dict[str, str]:
    """A ghostty theme file's colours, as ghostty-web's theme keys ({} if there is no file)."""
    theme: dict[str, str] = {}
    if not path.is_file():
        return theme
    for line in path.read_text(errors="replace").splitlines():
        key, _, value = (part.strip() for part in line.partition("="))
        if key == "palette":
            index, _, color = value.partition("=")
            if index.strip().isdigit() and int(index) < len(ANSI):
                theme[ANSI[int(index)]] = color.strip()
        elif key in GHOSTTY_KEYS and value:
            color = value.strip('"')
            theme[GHOSTTY_KEYS[key]] = color if color.startswith("#") else f"#{color}"
    return theme


def terminal_theme(path: Path = OMARCHY_GHOSTTY_THEME) -> dict[str, str]:
    """The Terminal pane's colours as ghostty-web's theme: your Omarchy ghostty theme's
    (background, text, cursor, selection and the 16 ANSI colours), the repo's Everforest
    (ghostty-everforest.conf) for any it lacks, or all of them without Omarchy.
    """
    return read_ghostty_theme(EVERFOREST_THEME) | read_ghostty_theme(path)


async def screen_scale() -> float:
    """The focused monitor's scale (Hyprland), so a scaled display gets the same size; 1 if
    it can't be read (not Hyprland, or hyprctl is slow).
    """
    with contextlib.suppress(Exception):
        proc = await asyncio.create_subprocess_exec(
            "hyprctl", "monitors", "-j", stdout=asyncio.subprocess.PIPE, stderr=asyncio.subprocess.DEVNULL
        )
        out, _ = await asyncio.wait_for(proc.communicate(), 1)
        monitors = json.loads(out)
        return float(next((m for m in monitors if m.get("focused")), monitors[0])["scale"])
    return 1.0


async def page(_request: object) -> HTMLResponse:
    """GET /terminal: the page the Terminal pane frames, its text sized and coloured as your
    terminal.
    """
    theme = terminal_theme()
    sizes = {
        "FONT_PT": str(terminal_font_pt()),
        "SCREEN_SCALE": str(await screen_scale()),
        "THEME_JSON": json.dumps(theme),
        "THEME_BACKGROUND": theme["background"],
    }
    html = PAGE
    for name, value in sizes.items():
        html = html.replace(name, value)
    return HTMLResponse(html, headers={"Content-Security-Policy": FRAME_ANCESTORS})


def allowed_origin(origin: str, client_host: str) -> bool:
    """Whether a WebSocket may start a shell: it comes from this machine, from a page on this
    machine (the app's, eg http://localhost:8000). A page on any other site is refused.
    """
    return client_host in LOCAL_HOSTS and urlsplit(origin).hostname in LOCAL_HOSTS


def _set_size(fd: int, cols: int, rows: int) -> None:
    fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack("HHHH", max(rows, 1), max(cols, 1), 0, 0))


async def shell_socket(ws: WebSocket) -> None:
    """/terminal/ws: one shell per connection, in a pseudo-terminal. Text from the page is
    typed into it (a {"type": "resize"} message resizes it); what it prints goes back as text.
    The shell is hung up when the page goes (the widget closed or re-mounted).
    """
    client = ws.client.host if ws.client else ""
    if not allowed_origin(ws.headers.get("origin", ""), client):
        await ws.close(code=1008)  # policy violation: not from this machine's pages
        return
    await ws.accept()
    # no fork of this (threaded) server running Python in the child: util-linux's `setsid
    # --ctty` gives the shell a session of its own with the pty as its terminal
    fd, tty = pty.openpty()
    _set_size(fd, int(ws.query_params.get("cols", 80)), int(ws.query_params.get("rows", 24)))
    shell = shell_command()
    # the user's own login shell, by design; setsid is util-linux's, from PATH
    proc = await asyncio.create_subprocess_exec(
        "setsid",
        "--ctty",
        shell,
        "-l",
        stdin=tty,
        stdout=tty,
        stderr=tty,
        env={**os.environ, "TERM": "xterm-256color"},
        cwd=Path.home(),
    )
    os.close(tty)  # the shell holds it now
    loop = asyncio.get_running_loop()
    output: asyncio.Queue[bytes] = asyncio.Queue()

    def readable() -> None:
        try:
            output.put_nowait(os.read(fd, READ_SIZE))
        except OSError:  # the shell exited: the pty is closed
            loop.remove_reader(fd)
            output.put_nowait(b"")

    loop.add_reader(fd, readable)

    ended = asyncio.Event()  # the shell is gone and all it printed was sent

    async def pump_out() -> None:
        decoder = codecs.getincrementaldecoder("utf-8")(errors="replace")
        while chunk := await output.get():
            await ws.send_text(decoder.decode(chunk))
        ended.set()

    async def shell_exit() -> None:
        # the shell itself ended (eg `exit`): say so now. The pty alone doesn't tell while
        # something the shell started still holds it open
        await proc.wait()
        output.put_nowait(b"")

    sender = asyncio.create_task(pump_out())
    waiter = asyncio.create_task(shell_exit())
    gone = asyncio.create_task(ended.wait())
    try:
        while True:
            # also wake when the shell ends: the socket is closed by returning from here (a
            # close sent from another task, while this one waits for a message, is not sent
            # by the app's server until then)
            receive = asyncio.create_task(ws.receive_text())
            await asyncio.wait({receive, gone}, return_when=asyncio.FIRST_COMPLETED)
            if not receive.done():
                receive.cancel()
                break
            message = receive.result()
            if message.startswith('{"type":"resize"'):
                size = json.loads(message)
                _set_size(fd, int(size["cols"]), int(size["rows"]))
            else:
                os.write(fd, message.encode())
        with contextlib.suppress(Exception):
            await ws.close()
    except Exception:  # noqa: BLE001, S110  # the page went away (a disconnect): hang up below
        pass
    finally:
        for task in (sender, waiter, gone):
            task.cancel()
        loop.remove_reader(fd)
        with contextlib.suppress(ProcessLookupError):
            os.killpg(proc.pid, signal.SIGHUP)  # the shell's session: it and what it started
        with contextlib.suppress(OSError):
            os.close(fd)
        await proc.wait()
